\begin{tikzpicture}[font=\sffamily, scale=1]
    % Axes
    \draw[-Stealth, thick] (0,0) -- (7,0) node[anchor=north] {Partial pressure of oxygen / kPa};
    \draw[-Stealth, thick] (0,0) -- (0,6) node[anchor=east, align=right] {Percentage\\saturation\\of haemoglobin / \%};

    % Y-axis ticks and labels
    \foreach \y/%
    \lab in {0/0, 1.2/20, 2.4/40, 3.6/60, 4.8/80, 6/100} {
        \draw (0,\y) -- (-0.1,\y);
        \node[anchor=east] at (-0.1,\y) {\lab};
    }

    % X-axis ticks and labels
    \foreach \x/%
    \lab in {1.2/2, 2.4/4, 3.6/6, 4.8/8, 6/10} {
        \draw (\x,0) -- (\x,-0.1);
        \node[anchor=north] at (\x,-0.1) {\lab};
    }
    % Add 12, 14
    \draw (7.2,0) -- (7.2,-0.1); % just to extend a bit visually if needed, or keep up to 12
    \node[anchor=north] at (7.2,-0.1) {}; 

    % Adjusting X scale for 0 to 14 kPa
    % Let 1 kPa = 0.5 cm. Max 14 kPa = 7 cm.
    % Let's redefine coordinates for better spacing: 
    % 0 to 14 kPa on x-axis. 14 cm total width. 
    % Let's use scale=0.8
\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=0.85]
    % Axes
    \draw[-Stealth, thick] (0,0) -- (9.5,0) node[anchor=north] {Partial pressure of oxygen / kPa};
    \draw[-Stealth, thick] (0,0) -- (0,6.5) node[anchor=east, align=right, font=\small] {Percentage\\saturation\\of haemoglobin / \%};

    % Y-axis ticks and labels (0 to 100%)
    \foreach \y/\lab in {0/0, 1.2/20, 2.4/40, 3.6/60, 4.8/80, 6/100} {
        \draw (0,\y) -- (-0.1,\y);
        \node[anchor=east, font=\small] at (-0.1,\y) {\lab};
    }

    % X-axis ticks and labels (0 to 14 kPa)
    % Let 1 kPa = 0.6 cm -> 14 kPa = 8.4 cm
    \foreach \x/\lab in {0.6/2, 1.8/6, 3.0/10, 4.2/14} {
        % Wait, let's map carefully: 
        % 0 kPa = 0
        % 2 kPa = 1.2
        % 4 kPa = 2.4
        % 6 kPa = 3.6
        % 8 kPa = 4.8
        % 10 kPa = 6.0
        % 12 kPa = 7.2
        % 14 kPa = 8.4
    }

    \foreach \x/\lab in {1.2/2, 2.4/4, 3.6/6, 4.8/8, 6.0/10, 7.2/12, 8.4/14} {
        \draw (\x,0) -- (\x,-0.1);
        \node[anchor=north, font=\small] at (\x,-0.1) {\lab};
    }

    % Curve A (left shifted)
    % Sigmoidal shape using bezier or plot
    \draw[thick] (0,0) .. controls (1.5,0.2) and (2.0,1.5) .. (3.0,3.6) 
                 .. controls (4.0,5.5) and (6.0,5.9) .. (8.4,6.0);

    % Curve B (right shifted)
    \draw[thick, dashed] (0,0) .. controls (2.0,0.2) and (2.8,1.2) .. (4.2,3.6) 
                         .. controls (5.5,5.2) and (7.0,5.9) .. (8.4,6.0);

    % Labels for curves
    \node[font=\bfseries] at (2.2, 4.8) {A};
    \node[font=\bfseries] at (3.5, 2.3) {B};

    % Caption
    \node[font=\bfseries] at (4.2, -1.2) {Fig. 7.1};

\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=0.85]
    % Axes
    \draw[-Stealth, thick] (0,0) -- (9.5,0) node[anchor=north, font=\small] at (7.2,-0.1) {Partial pressure of oxygen / kPa};
    \draw[-Stealth, thick] (0,0) -- (0,6.5);
    \node[anchor=south, font=\small, align=center] at (0,6.6) {Percentage\\saturation\\of haemoglobin / \%};

    % Y-axis ticks and labels (0 to 100%)
    \foreach \y/\lab in {0/0, 1.2/20, 2.4/40, 3.6/60, 4.8/80, 6/100} {
        \draw (0,\y) -- (-0.1,\y);
        \node[anchor=east, font=\small] at (-0.1,\y) {\lab};
    }

    % X-axis ticks and labels (0 to 14 kPa)
    \foreach \x/\lab in {1.2/2, 2.4/4, 3.6/6, 4.8/8, 6.0/10, 7.2/12, 8.4/14} {
        \draw (\x,0) -- (\x,-0.1);
        \node[anchor=north, font=\small] at (\x,-0.1) {\lab};
    }

    % Curve A (left shifted) - solid line
    \draw[thick] (0,0) .. controls (1.5,0.2) and (2.0,1.5) .. (3.0,3.6) 
                 .. controls (4.0,5.5) and (6.0,5.9) .. (8.4,6.0);

    % Curve B (right shifted) - solid or dashed? Standard is solid or dashed depending on convention, let's use solid for both or one dashed, standard Cambridge often uses two solid or one dashed. Let's make both solid as typical in some variants, or one dashed. The previous used dashed for B. Let's keep it clear.
    \draw[thick] (0,0) .. controls (2.0,0.2) and (2.8,1.2) .. (4.2,3.6) 
                 .. controls (5.5,5.2) and (7.0,5.9) .. (8.4,6.0);

    % Labels for curves
    \node[font=\bfseries] at (2.4, 4.8) {A};
    \node[font=\bfseries] at (4.2, 2.3) {B};

    % Caption
    \node[font=\small] at (4.2, -1.0) {Fig. 7.1};

\end{tikzpicture}
